PRAGMA foreign_keys = ON;
CREATE TABLE users (id TEXT PRIMARY KEY, email TEXT NOT NULL COLLATE NOCASE UNIQUE, name TEXT NOT NULL, password_hash TEXT NOT NULL, verified INTEGER NOT NULL DEFAULT 0, disabled INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL);
CREATE TABLE guests (id TEXT PRIMARY KEY, created_at TEXT NOT NULL);
CREATE TABLE sessions (hash TEXT PRIMARY KEY, user_id TEXT REFERENCES users(id) ON DELETE CASCADE, guest_id TEXT REFERENCES guests(id), expires_at TEXT NOT NULL);
CREATE INDEX sessions_user ON sessions(user_id);
CREATE TABLE admins (id TEXT PRIMARY KEY, username TEXT NOT NULL COLLATE NOCASE UNIQUE, password_hash TEXT NOT NULL, must_change INTEGER NOT NULL DEFAULT 1, disabled INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL);
CREATE TABLE admin_sessions (hash TEXT PRIMARY KEY, admin_id TEXT NOT NULL REFERENCES admins(id) ON DELETE CASCADE, expires_at TEXT NOT NULL);
CREATE TABLE tokens (hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, purpose TEXT NOT NULL CHECK(purpose IN ('verify','reset')), expires_at TEXT NOT NULL);
CREATE TABLE trips (id TEXT PRIMARY KEY, user_id TEXT REFERENCES users(id) ON DELETE CASCADE, guest_id TEXT REFERENCES guests(id), title TEXT NOT NULL, destination TEXT NOT NULL DEFAULT '', preferences TEXT NOT NULL DEFAULT '{}', itinerary TEXT NOT NULL DEFAULT '[]', version INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, CHECK(user_id IS NOT NULL OR guest_id IS NOT NULL));
CREATE INDEX trips_user ON trips(user_id,created_at);
CREATE INDEX trips_guest ON trips(guest_id,created_at);
CREATE TABLE messages (id TEXT PRIMARY KEY, trip_id TEXT NOT NULL REFERENCES trips(id) ON DELETE CASCADE, role TEXT NOT NULL CHECK(role IN ('user','assistant')), content TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE INDEX messages_trip ON messages(trip_id,created_at);
CREATE TABLE usage (id TEXT PRIMARY KEY, timestamp TEXT NOT NULL, provider TEXT NOT NULL, model TEXT NOT NULL, operation TEXT NOT NULL, user_id TEXT, guest_id TEXT, trip_id TEXT, status TEXT NOT NULL, input_tokens INTEGER NOT NULL DEFAULT 0, output_tokens INTEGER NOT NULL DEFAULT 0, cached_tokens INTEGER NOT NULL DEFAULT 0, units INTEGER NOT NULL DEFAULT 1, cost REAL, currency TEXT NOT NULL DEFAULT 'USD', pricing TEXT NOT NULL, duration_ms INTEGER NOT NULL, error TEXT);
CREATE INDEX usage_time ON usage(timestamp);
CREATE INDEX usage_trip ON usage(trip_id);
CREATE INDEX usage_user ON usage(user_id);
CREATE TABLE audit (id TEXT PRIMARY KEY, timestamp TEXT NOT NULL, actor TEXT, action TEXT NOT NULL, target TEXT, outcome TEXT NOT NULL);
CREATE TABLE rate_limits (key TEXT PRIMARY KEY, count INTEGER NOT NULL, expires INTEGER NOT NULL);
CREATE TABLE settings (key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE errors (id TEXT PRIMARY KEY, timestamp TEXT NOT NULL, category TEXT NOT NULL, code TEXT NOT NULL);
CREATE TRIGGER protect_last_admin_delete BEFORE DELETE ON admins WHEN OLD.disabled = 0 AND (SELECT COUNT(*) FROM admins WHERE disabled=0)<=1 BEGIN SELECT RAISE(ABORT,'Cannot remove the last active administrator'); END;
CREATE TRIGGER protect_last_admin_disable BEFORE UPDATE OF disabled ON admins WHEN NEW.disabled=1 AND OLD.disabled=0 AND (SELECT COUNT(*) FROM admins WHERE disabled=0)<=1 BEGIN SELECT RAISE(ABORT,'Cannot disable the last active administrator'); END;
